#!/usr/bin/env python3
"""Bounded Facebook supplement installation; no account/session import."""
import base64,datetime as dt,fcntl,hashlib,json,os,pathlib,pwd,shutil,sqlite3,subprocess,sys,tempfile,time,urllib.request,urllib.error
APP=pathlib.Path('/opt/umraniye-osint-deneme')
FB=pathlib.Path('/opt/umraniye-osint-facebook-fbgql-deneme')
SOURCE=pathlib.Path('/var/lib/umraniye-osint-facebook-fbgql-deneme')
STATE=pathlib.Path('/var/lib/umraniye-osint-facebook-supplement')
SITE='umraniye-osint-deneme.service'
COLLECTOR='umraniye-osint-facebook-fbgql-deneme.service'
PUB='umraniye-osint-facebook-supplement-publish.service'
TIMER='umraniye-osint-facebook-fbgql-deneme.timer'
EXPECTED={'worker.py': '3baa44f75031a6e4402433ea2bc0ca5e103c905bd1747a0750767bec37ad067d', 'reader.py': 'c0e4c21d7bf0d9b83e14c0c291ae3e57d61c7e23f3d0d3e70a832ca557a5dff6', 'prepare.py': '0c676939dc6d48a8aab2f21d31008e5974baa3c54c18bc7fe62fe8b633d0707e'}
BACKEND_EXPECTED='9707e40de23b493bd5ec0a099a48b7377a180e164b34647644ba9013f8fd4e35'
PAYLOAD={'reader.py': '', 'worker.py': '', 'prepare.py': '', 'publish.py': '', 'adapter.mjs': '', 'rules-manifest.json': '', 'README.md': '', 'test_worker.py': '', 'test_publish.py': '', 'test_backend.mjs': '', 'rules/package.json': 'eyJ0eXBlIjoibW9kdWxlIiwicHJpdmF0ZSI6dHJ1ZX0=', 'rules/server/central-keywords.mjs': '', 'rules/server/facebook-display-model.mjs': '', 'rules/server/geo-dictionary-data.mjs': '', 'rules/server/geo-dictionary.mjs': '', 'rules/server/governor-activity.mjs': '', 'rules/server/institutional-reference.mjs': '', 'rules/server/local-scope-policy.mjs': '', 'rules/server/local-sports.mjs': '', 'rules/server/location-review.mjs': '', 'rules/server/social-quality.mjs': '', 'rules/server/social-source-context.mjs': '', 'rules/src/intelligence.js': '', 'rules/src/newsworthiness.js': '', 'rules/server/filters/umraniyespor.mjs': ''}
EXTRAS={'browser-research.next.mjs': '', 'publisher.service': '', 'collector.timer': '', 'collector.conf': 'W1NlcnZpY2VdClRpbWVvdXRTdGFydFNlYz0yNDAKRXhlY1N0YXJ0UG9zdD0rL3Vzci9iaW4vc3lzdGVtY3RsIC0tbm8tYmxvY2sgc3RhcnQgdW1yYW5peWUtb3NpbnQtZmFjZWJvb2stc3VwcGxlbWVudC1wdWJsaXNoLnNlcnZpY2UK'}
def run(args,timeout=30,env=None):return subprocess.run(args,capture_output=True,text=True,timeout=timeout,env=env)
def put(p,data):
 p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_name(p.name+'.install-tmp');tmp.write_bytes(data);tmp.chmod(0o644);tmp.replace(p)
class NoRedirect(urllib.request.HTTPRedirectHandler):
 def redirect_request(self,*a,**k):raise RuntimeError('redirect_denied')
def probe(key=None):
 req=urllib.request.Request('http://127.0.0.1:3001/api/admin/integrations/browser-worker',headers={'X-OSINT-Browser-Key':key} if key else {})
 try:
  with urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect()).open(req,timeout=15) as r:return r.status
 except urllib.error.HTTPError as e:return e.code

def main():
 if os.geteuid()!=0:raise RuntimeError('sudo_required')
 if any(p.is_symlink() for p in [FB,APP,SOURCE,STATE]):raise RuntimeError('symlink_destination_denied')
 for n,h in EXPECTED.items():
  if hashlib.sha256((FB/n).read_bytes()).hexdigest()!=h:raise RuntimeError('reader_version_changed_no_install:'+n)
 backend=APP/'server/browser-research.mjs'
 if hashlib.sha256(backend.read_bytes()).hexdigest()!=BACKEND_EXPECTED:raise RuntimeError('backend_version_changed_no_install')
 if run(['systemctl','show',COLLECTOR,'--property=ActiveState','--value']).stdout.strip() in ('active','activating','reloading'):raise RuntimeError('facebook_shadow_busy_no_install')
 pubpath=pathlib.Path('/etc/systemd/system')/PUB;timerpath=pathlib.Path('/etc/systemd/system')/TIMER;drop=pathlib.Path('/etc/systemd/system')/(COLLECTOR+'.d/zz-supplement.conf')
 if any(p.exists() for p in [pubpath,timerpath,drop]):raise RuntimeError('supplement_already_configured')
 with tempfile.TemporaryDirectory(prefix='facebook-supplement-check-') as d:
  stage=pathlib.Path(d)
  for n,data in PAYLOAD.items():put(stage/n,base64.b64decode(data))
  for test in ['test_worker.py','test_publish.py']:
   result=run([str(FB/'venv/bin/python'),str(stage/test)],60)
   if result.returncode:raise RuntimeError('offline_test_failed_no_install:'+test)
  # Validate all reviewed rules against real source files, without DB writes.
  manifest=json.loads((stage/'rules-manifest.json').read_text())
  for n,digest in manifest.items():
   if hashlib.sha256((APP/n).read_bytes()).hexdigest()!=digest:raise RuntimeError('shared_rule_changed_no_install:'+n)
  clone=stage/'application';clone.mkdir()
  for folder,dirs,names in os.walk(APP,followlinks=False):
   dirs[:]=[n for n in dirs if not n.startswith('.') and n not in {'node_modules','backups','data','logs','profiles','venv'} and not (pathlib.Path(folder)/n).is_symlink()]
   for n in names:
    src=pathlib.Path(folder)/n
    if not src.is_symlink() and (src.suffix in {'.mjs','.js','.cjs','.html','.png'} or n=='package.json'):
     dest=clone/src.relative_to(APP);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dest)
  put(clone/'server/browser-research.mjs',base64.b64decode(EXTRAS['browser-research.next.mjs']))
  test=run(['node',str(stage/'test_backend.mjs'),str(clone/'server/browser-research.mjs')],60,env={**os.environ,'DATA_DIR':str(stage/'fixture-state')})
  if test.returncode:raise RuntimeError('facebook_and_x_admission_tests_failed_no_install')
 backup=pathlib.Path('/var/lib/umraniye-osint-deneme/backups')/('facebook-supplement-'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'));backup.mkdir(parents=True,mode=0o700)
 files={FB/n:base64.b64decode(v) for n,v in PAYLOAD.items()};files[backend]=base64.b64decode(EXTRAS['browser-research.next.mjs']);files[pubpath]=base64.b64decode(EXTRAS['publisher.service']);files[timerpath]=base64.b64decode(EXTRAS['collector.timer']);files[drop]=b'[Service]\nTimeoutStartSec=240\n'
 old={str(p):base64.b64encode(p.read_bytes()).decode() if p.exists() else None for p in files}
 rollback="""#!/usr/bin/env python3
import base64,pathlib,subprocess
OLD=__OLD__
subprocess.run(['systemctl','disable','--now','umraniye-osint-facebook-fbgql-deneme.timer'],capture_output=True)
subprocess.run(['systemctl','stop','umraniye-osint-facebook-fbgql-deneme.service','umraniye-osint-facebook-supplement-publish.service'],capture_output=True)
for name,data in OLD.items():
 p=pathlib.Path(name)
 if data is None:p.unlink(missing_ok=True)
 else:p.write_bytes(base64.b64decode(data));p.chmod(0o644)
subprocess.run(['systemctl','daemon-reload'],check=True)
subprocess.run(['systemctl','restart','umraniye-osint-deneme.service'],check=True)
print('Facebook ek okuyucu geri alindi; olay verileri ve hesap profilleri korundu.')
""".replace('__OLD__',repr(old))
 (backup/'geri-al.py').write_text(rollback)
 con=sqlite3.connect('file:/var/lib/umraniye-osint-deneme/osint.sqlite?mode=ro',uri=True);saved=sqlite3.connect(backup/'osint.sqlite');con.backup(saved);saved.close();con.close()
 prod=run(['systemctl','show','umraniye-osint.service','--property=ExecMainStartTimestampMonotonic','--value']).stdout.strip()
 STATE.mkdir(parents=True,exist_ok=True,mode=0o700);STATE.chmod(0o700)
 lock=open(SOURCE/'run.lock','a');who=pwd.getpwnam('osintfbshadow');os.fchown(lock.fileno(),who.pw_uid,who.pw_gid);os.fchmod(lock.fileno(),0o600);fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 changed=False
 try:
  changed=True
  for p,data in files.items():
   if p.is_symlink():raise RuntimeError('symlink_file_denied')
   put(p,data)
  if run(['systemd-analyze','verify',str(pubpath),str(timerpath)]).returncode:raise RuntimeError('unit_validation_failed')
  if run(['systemctl','daemon-reload']).returncode:raise RuntimeError('daemon_reload_failed')
  if run(['systemctl','restart',SITE],60).returncode:raise RuntimeError('application_restart_failed')
  for _ in range(30):
   try:
    if probe()==404:break
   except Exception:pass
   time.sleep(1)
  else:raise RuntimeError('application_service_route_unhealthy')
  key=pathlib.Path('/var/lib/umraniye-osint-deneme/browser-service.key')
  if probe(key.read_bytes().hex())!=200:raise RuntimeError('service_auth_failed')
 except Exception:
  lock.close()
  if changed:run(['python3',str(backup/'geri-al.py')],90)
  raise
 lock.close()
 first=run(['systemctl','start',COLLECTOR],260)
 report=json.loads((SOURCE/'report.json').read_text()) if (SOURCE/'report.json').exists() else {'status':'missing_report'}
 # Only the newly requested round can qualify, never an old successful report.
 newRound=report.get('maximumSourcesPerRound')==10 and first.returncode==0
 readVerified=newRound and report.get('uniqueRead',0)>0 and any(r.get('status')=='read_completed' and r.get('read',0)>0 for r in report.get('sources',[]))
 delivery=run(['systemctl','start',PUB],100)
 published=json.loads((STATE/'report.json').read_text()) if (STATE/'report.json').exists() else {'status':'missing_report'}
 enabled=readVerified and delivery.returncode==0
 if enabled:
  put(drop,base64.b64decode(EXTRAS['collector.conf']))
  if run(['systemctl','daemon-reload']).returncode or run(['systemctl','enable','--now',TIMER]).returncode:
   run(['python3',str(backup/'geri-al.py')],90)
   raise RuntimeError('timer_enable_failed_code_rolled_back')
 prodAfter=run(['systemctl','show','umraniye-osint.service','--property=ExecMainStartTimestampMonotonic','--value']).stdout.strip()
 result={'result':'facebook_supplement_enabled' if enabled else 'facebook_supplement_installed_verification_pending','enabled':enabled,'intervalMinutesAfterCompletedRound':5 if enabled else None,'anonymous':True,'browserStarted':False,'liveReadVerified':readVerified,'newFreshPostStoredVerified':published.get('confirmedInExistingStorage',0)>0,'externalBrowserVerified':False,'existingBrowserHealthPreserved':True,'existingXReaderPreserved':True,'telegramSettingsChanged':False,'historicalReplay':False,'productionServiceUnchanged':prod==prodAfter,'offlineWorkerAndPublisherTestsPassed':8,'xAndFacebookAdmissionChecksPassed':True,'collection':report,'publisher':published,'backup':str(backup),'rollback':'sudo python3 '+str(backup/'geri-al.py')}
 (STATE/'installation-report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False,indent=2))

if __name__=='__main__':
 try:main()
 except Exception as e:print('KURULAMADI: '+(str(e) if isinstance(e,RuntimeError) else type(e).__name__));sys.exit(1)
